func ftNameRow(rows []byte, from int32, to int32, ar *port.Cells, f *port.Cells, kind int32, t *strings.Builder) int32 {
	// Parse the /name at rows[from, to) and write its code points (kind 110,
	// `n`; 122, `z`, for ZapfDingbats) or the standard font its BaseFont means
	// (kind 115, `s`).
	var h int32 = 0
	var cnt int32 = 0
	pdflex.PlInit(ar)
	pdflex.PlSeek(ar, from, to)
	h = pdflex.PlParse(port.SrcOfBlob(rows), ar)
	if h == 0 {
		port.TextAscii(t, "!parse")
		return 0
	}
	if pdflex.PlKindOf(ar, h) != 4 {
		port.TextAscii(t, "!notname")
		return 0
	}
	if kind == 110 {
		cnt = pdffont.PfnNameCps(f, ar, h)
		ftEmitCps(t, f, cnt)
	}
	if kind == 122 {
		cnt = pdffont.PfnNameCpsZapf(f, ar, h)
		ftEmitCps(t, f, cnt)
	}
	if kind == 115 {
		port.TextI32(t, pdffont.PfnS14Of(ar, h))
	}
	return 0
}

