func ftKindCode(c int32) int32 {
	// simple -> 1, composite -> 2, none -> 0, by the first letter.
	if c == 115 {
		return 1
	}
	if c == 99 {
		return 2
	}
	return 0
}

func ftLoadFont(rows []byte, from int32, to int32, num int32, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, out *port.Cells, f *port.Cells) int32 {
	// Open the file named by rows[from, to), load font object `num`, and answer
	// the `pfn-status`, or 100 + the `pd-open` status when the file will not open.
	var pdf *port.Src = port.SrcOfBlob(port.TestFileSpan(rows, from, to))
	var ostatus int32 = pdfdoc.PdOpen(pdf, ar, dc, a, b, st)
	var h int32 = 0
	if ostatus != 0 {
		return 100 + ostatus
	}
	h = pdfdoc.PdGet(pdf, ar, dc, a, b, st, num)
	return pdffont.PfnLoad(pdf, ar, dc, a, b, st, f, out, h)
}

func ftCodeRow(rows []byte, s0 int32, s1 int32, f *port.Cells, cps *strings.Builder, how *strings.Builder) int32 {
	// Map the hex code at rows[s0+1, s1) and write its code points and `how`;
	// answers its width.
	var code int32 = ftHex(rows, s0+1, s1)
	var cnt int32 = pdffont.PfnMap(f, code)
	ftEmitCps(cps, f, cnt)
	pdffont.PfnHowEmitName(how, pdffont.PfnHowOf(f))
	return pdffont.PfnWidth(f, code)
}

func ftLenRow(rows []byte, s0 int32, s1 int32, f *port.Cells) int32 {
	return pdffont.PfnCodeLen(f, ftByteAt(rows, s0+1, s1, 0), ftByteAt(rows, s0+1, s1, 1), ftByteAt(rows, s0+1, s1, 2), ftByteAt(rows, s0+1, s1, 3))
}

func TestEveryFixtureFontAnswersAsBuilt(emonT *testing.T) {
	// Rows of fonts.txt: font, then its code, len, cid and dw2 rows.
	var rows []byte = port.TestFile("fonts/fonts.txt")
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var f *port.Cells = port.NewCells()
	var n int32 = port.BlobLen(rows)
	var pos int32 = 0
	var line int32 = 0
	var count int32 = 0
	var e int32 = 0
	var s0 int32 = 0
	var s1 int32 = 0
	var s2 int32 = 0
	var s3 int32 = 0
	var s4 int32 = 0
	var s5 int32 = 0
	var s6 int32 = 0
	var s7 int32 = 0
	var s8 int32 = 0
	var lstatus int32 = 0
	var b0 int32 = 0
	var b1 int32 = 0
	var width int32 = 0
	for pos < n {
		line += 1
		e = ftNl(rows, pos)
		if (pos < e) && (port.BlobU8(rows, pos) != 35) {
			count += 1
			b0 = port.BlobU8(rows, pos)
			b1 = port.BlobU8(rows, pos+1)
			s0 = ftTab(rows, pos, e)
			s1 = ftTab(rows, s0+1, e)
			s2 = ftTab(rows, s1+1, e)
			s3 = ftTab(rows, s2+1, e)
			if b0 == 102 {
				s4 = ftTab(rows, s3+1, e)
				s5 = ftTab(rows, s4+1, e)
				s6 = ftTab(rows, s5+1, e)
				s7 = ftTab(rows, s6+1, e)
				s8 = ftTab(rows, s7+1, e)
				lstatus = ftLoadFont(rows, s0+1, s1, ftDec(rows, s1+1, s2), ar, dc, a, b, st, out, f)
				port.AssertEqAt(emonT, lstatus, ftDec(rows, s2+1, s3), "load status", line)
				if lstatus == 0 {
					port.AssertEqAt(emonT, pdffont.PfnKindOf(f), ftKindCode(port.BlobU8(rows, s3+1)), "kind", line)
					port.AssertEqAt(emonT, pdffont.PfnAscent(f), ftDec(rows, s4+1, s5), "ascent", line)
					port.AssertEqAt(emonT, pdffont.PfnDescent(f), ftDec(rows, s5+1, s6), "descent", line)
					port.AssertEqAt(emonT, pdffont.PfnWarn(f), ftDec(rows, s6+1, s7), "warning bits", line)
					port.AssertEqAt(emonT, pdffont.PfnVertical(f), ftDec(rows, s7+1, s8), "vertical", line)
					port.AssertEqAt(emonT, pdffont.PfnStandardFont(f), ftDec(rows, s8+1, e), "standard font", line)
				}
			}
			if (b0 == 99) && (b1 == 111) {
				var tcps *strings.Builder = port.NewText()
				var thow *strings.Builder = port.NewText()
				width = ftCodeRow(rows, s0, s1, f, tcps, thow)
				port.AssertTextSpan(emonT, tcps, rows, s1+1, s2, "code points", line)
				port.AssertTextSpan(emonT, thow, rows, s2+1, s3, "how", line)
				port.AssertEqAt(emonT, width, ftDec(rows, s3+1, e), "width", line)
			}
			if (b0 == 99) && (b1 == 105) {
				port.AssertEqAt(emonT, pdffont.PfnCid(f, ftHex(rows, s0+1, s1)), ftDec(rows, s1+1, e), "cid", line)
			}
			if b0 == 108 {
				port.AssertEqAt(emonT, ftLenRow(rows, s0, s1, f), ftDec(rows, s1+1, e), "code length", line)
			}
			if b0 == 100 {
				port.AssertEqAt(emonT, pdffont.PfnDw2V(f), ftDec(rows, s1+1, s2), "DW2 v", line)
				port.AssertEqAt(emonT, pdffont.PfnDw2W(f), ftDec(rows, s2+1, e), "DW2 w1", line)
			}
		}
		pos = e + 1
	}
	port.AssertThat(emonT, count > 150, "the font rows were read")
}

